import { afterEach, describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

/**
 * The gate reads packages/server/src from the repo it lives in, so a fixture
 * has to be a real file under that tree. Each case writes one, runs the gate,
 * and removes it — the file name is unique per case so a crashed run cannot
 * leave a fixture that fails everyone else's gate.
 */
const REPO_ROOT = path.resolve(import.meta.dir, "..", "..");
const SERVER_SRC = path.join(REPO_ROOT, "packages", "server", "src");
const FIXTURE_DIR = path.join(SERVER_SRC, "__gate_fixtures__");

const written: string[] = [];

function runGateAgainst(source: string): { code: number; output: string } {
  mkdirSync(FIXTURE_DIR, { recursive: true });
  const file = path.join(FIXTURE_DIR, `fixture-${written.length}.ts`);
  writeFileSync(file, source);
  written.push(file);

  const result = spawnSync(
    process.execPath,
    [path.join(REPO_ROOT, "scripts", "check-gateway-llm-calls.mjs")],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  return {
    code: result.status ?? -1,
    output: `${result.stdout ?? ""}${result.stderr ?? ""}`,
  };
}

afterEach(() => {
  for (const f of written.splice(0)) rmSync(f, { force: true });
  rmSync(FIXTURE_DIR, { recursive: true, force: true });
});

describe("gateway-llm gate catches hand-rolled completion calls", () => {
  test("flags a same-line completion fetch", () => {
    const { code, output } = runGateAgainst(
      `export async function call() {\n` +
        `  return fetch("https://api.example.com/v1/chat/completions");\n` +
        `}\n`,
    );
    expect(code).toBe(1);
    expect(output).toContain("hand-rolled completion fetch");
  });

  test("flags a MULTILINE completion fetch", () => {
    // The shape an ordinary formatter produces. The gate used to match
    // `fetch(` and the completion path on one PHYSICAL line, so this — the
    // most likely way the violation actually gets written — sailed through.
    const { code, output } = runGateAgainst(
      `export async function call() {\n` +
        `  return fetch(\n` +
        `    "https://api.example.com/v1/chat/completions",\n` +
        `    { method: "POST" },\n` +
        `  );\n` +
        `}\n`,
    );
    expect(code).toBe(1);
    expect(output).toContain("hand-rolled completion fetch");
  });

  test("does not flag a fetch with no completion path", () => {
    const { code } = runGateAgainst(
      `export async function call() {\n` +
        `  return fetch(\n` +
        `    "https://api.example.com/v1/models",\n` +
        `  );\n` +
        `}\n`,
    );
    expect(code).toBe(0);
  });

  test("honors an inline suppression on a multiline fetch", () => {
    const { code } = runGateAgainst(
      `export async function call() {\n` +
        `  // gateway-llm-ok: fixture proving suppression still applies\n` +
        `  return fetch(\n` +
        `    "https://api.example.com/v1/chat/completions",\n` +
        `  );\n` +
        `}\n`,
    );
    expect(code).toBe(0);
  });
});

