// 1. fetch() to a completions-style path.
//
// Match against the whole call expression, not the single physical line:
// a formatter routinely splits `fetch(` from its URL argument, and a
// line-local check silently exempted that — the most likely shape the
// violation actually gets written in.
if (/\bfetch\s*\(/.test(code)) {
  const callText = completionCallText(lines, i);
  for (const p of COMPLETION_PATHS) {
    if (callText.includes(p)) {
      flag(file, i + 1, "hand-rolled completion fetch", line);
      break;
    }
  }
}

/**
 * Text of the `fetch(...)` call that STARTS at `idx`, spanning however many
 * physical lines it takes to balance the opening paren.
 *
 * Why not just the one line: prettier/biome split a call the moment it exceeds
 * the print width, so the common violation is
 *
 *   return fetch(
 *     "https://host/v1/chat/completions",
 *   );
 *
 * where no single line holds both `fetch(` and the path. Depth counting stops
 * at the matching `)` so an unrelated later call cannot be dragged in, and a
 * bounded lookahead keeps a malformed file from scanning to EOF.
 */
function completionCallText(lines, idx) {
  const MAX_CALL_LINES = 40;
  let depth = 0;
  let started = false;
  const parts = [];
  for (let i = idx; i < lines.length && i < idx + MAX_CALL_LINES; i++) {
    const raw = lines[i];
    parts.push(raw);
    for (const ch of raw) {
      if (ch === "(") {
        depth++;
        started = true;
      } else if (ch === ")") {
        depth--;
      }
    }
    if (started && depth <= 0) break;
  }
  return parts.join("\n");
}

