 * PATH names the HASH-ADDRESSED profile, never the mutable `profile` symlink:
 * one sandbox serves every conversation for an (org, agent), so two execs with
 * different signed `nixPackages` both resolve that one symlink and the later
 * writer decides which tool set the earlier command sees. Addressing the exact
 * set keeps each exec on the packages ITS token was signed for. The path is
 * derived from `nixPackageSetHash` over route-validated names — a hex digest,
 * so nothing attacker-influenced reaches the command line.
 */
function withProvisionedPath(ctx: RuntimeExecContext): string {
  if (!ctx.provisioned || ctx.provisioned.failed.length > 0) return ctx.command;
  if (ctx.provisioned.installed.length === 0) return ctx.command;
  const marker = nixPackageSetHash(ctx.nixPackages ?? []);
  return `export PATH="${NIX_HOME}/profiles/${marker}/bin:$PATH"\n${ctx.command}`;
}

test("PATH names the exact package set, not the shared profile symlink", () => {
  // One sandbox serves every conversation for an (org, agent). Pointing PATH
  // at the mutable `profile` symlink let two execs with DIFFERENT signed
  // nixPackages resolve the same link — the later writer decided which tool
  // set the earlier command saw, breaking per-token package isolation.
  const ghCtx = {
    command: "gh --version",
    nixPackages: ["gh"],
    provisioned: { installed: ["gh"], failed: [], cached: true },
  } as never;
  const jqCtx = {
    command: "jq --version",
    nixPackages: ["jq"],
    provisioned: { installed: ["jq"], failed: [], cached: true },
  } as never;

  const gh = withProvisionedPath(ghCtx);
  const jq = withProvisionedPath(jqCtx);

  expect(gh).not.toContain("/profile/bin");
  expect(jq).not.toContain("/profile/bin");
  // Different package sets must resolve to different profile paths.
  const pathOf = (s: string) => s.match(/export PATH="([^:]+)/)?.[1];
  expect(pathOf(gh)).not.toBe(pathOf(jq));
  expect(pathOf(gh)).toContain("/profiles/");
});

